What will be the output of the following C code?
C

#include <stdio.h>int main() {
    int arr[] = {10, 20, 30, 40, 50};
    int *p = (int*)(&arr + 1);
    printf("%d", *(p - 2));
    return 0;
}

What is the output of the following C code demonstrating array indexing commutativity?
C

#include <stdio.h>int main() {
    int a[] = {5, 10, 15, 20};
    printf("%d", 2[a]);
    return 0;
}

What is the behavior of the following C code?
C

#include <stdio.h>#include <stdlib.h>int main() {
    int *p = (int*)malloc(sizeof(int));
    *p = 100;
    free(p);
    *p = 200;
    printf("%d", *p);
    return 0;
}

What will be the output of the following C++ code?
C++

#include <iostream>using namespace std;class Test {
    static int count;
public:
    Test() { count++; }
    static int getCount() { return count; }
};int Test::count = 0;int main() {
    Test t1, t2, t3;
    cout << Test::getCount();
    return 0;
}

What is the output of the following C++ program?
C++

#include <iostream>using namespace std;class A {public:
    virtual void print() { cout << "A "; }
};class B : public A {public:
    void print() override { cout << "B "; }
};class C : public B {public:
    void print() override { cout << "C "; }
};int main() {
    A *obj = new C();
    obj->print();
    return 0;
}

What is the output of the following snippet?
C++

#include <iostream>using namespace std;int main() {
    int i = 0;
    for (i = 0; i < 5; i++) {
        if (i == 2) continue;
        if (i == 4) break;
        cout << i << " ";
    }
    return 0;
}

What is the output of the following code?
C++

#include <iostream>using namespace std;void modify(const int *p) {
    int *q = const_cast<int*>(p);
    *q = 50;
}int main() {
    int val = 10;
    modify(&val);
    cout << val;
    return 0;
}
